"""Composition helpers: tracker note 49 == C-4 == 261.63 Hz."""
import numpy as np

NAMES = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']

def nn(name):
    """'C4' -> 49, 'A4' -> 58 (tracker note numbers)"""
    letter = name[0]; acc = 0; i = 1
    while i < len(name) and name[i] in '#b':
        acc += 1 if name[i]=='#' else -1
        i += 1
    octv = int(name[i:])
    return 12*octv + 1 + NAMES.index(letter) + acc

def freq_of_note(n):
    """tracker note number -> Hz"""
    midi = n + 11
    return 440.0*2**((midi-69)/12)

# natural frequency of each sample (pitch it plays at tracker note 49)
F0 = {
 'lead':  8363/19,
 'chip':  8363/19,
 'bass':  8363/76,
 'sub':   8363/152,
 'pad':   8363/38,
 'pluck': 8363/19,
 'arp':   8363/10,
}

def note_for_freq(instr, freq):
    """tracker note so that `instr` sounds at `freq`"""
    return int(round(49 + 12*np.log2(freq/F0[instr])))

def note_for_name(instr, name):
    return note_for_freq(instr, freq_of_note(nn(name)))

NOTE_OFF = 97
