            for r in range(0,BAR,2):
                out.append((r0+r, 2, 49, I['HatC']))
            out.append((r0+7, 2, 49, I['HatO']))
            out.append((r0+15, 2, 49, I['HatO']))
        elif style=='busy':
            for r in [0,3,6,8,11,14]:
                out.append((r0+r, 0, 49, I['Kick']))
            for r in [4,12]:
                out.append((r0+r, 1, 49, I['Snare']))
                out.append((r0+r, 2, 49, I['Clap']))
            for r in range(0,BAR,2):
                out.append((r0+r, 2, 49, I['HatC']))
            for r in [7,15]:
                out.append((r0+r, 2, 49, I['HatO']))
        elif style=='break':
            for r in [0,8]:
                out.append((r0+r, 0, 49, I['Kick']))
            for r in range(0,BAR,2):
                out.append((r0+r, 2, 49, I['HatC']))
            if b==3:
                for r in [8,10,12,14]:
                    out.append((r0+r, 1, 49, I['Snare']))
    return out

def bassline(pat, prog, style='octave', bars=4, instr='Bass'):
    out=[]
    for b in range(bars):
        ch = prog[b % len(prog)]
        root = CH[ch][0]
        r0=b*BAR
        if style=='octave':
            seq = [0,3,6,8,11,14]
            for i,r in enumerate(seq):
                nm = root if i%2==0 else nn_shift(root, 12)
                out.append((r0+r, 4, note_for_name(instr, nm), I[instr]))
        elif style=='pulse':
            for r in range(0,BAR,2):
                out.append((r0+r, 4, note_for_name(instr, root), I[instr]))
        elif style=='walk':
            steps=[0,2,4,6,8,10,12,14]
            tones = [0,0,7,0,0,7,0,7]
            for r,t in zip(steps,tones):
                nm = nn_shift(root, t)
                out.append((r0+r, 4, note_for_name(instr, nm), I[instr]))
    return out

def nn_shift(name, semi):
    """shift a note name by semitones"""
    n = nn(name) + semi
    return n

def subline(pat, prog, bars=4):
    out=[]
    for b in range(bars):
        ch = prog[b % len(prog)]
        root = nn(CH[ch][0])
        r0=b*BAR
        out.append((r0+0, 3, note_for_freq('sub', freq_of_note(root)), I['Sub']))
        out.append((r0+8, 3, note_for_freq('sub', freq_of_note(root)), I['Sub']))
    return out

def pad_chords(pat, prog, bars=4, chn=7):
    out=[]
    for b in range(bars):
        ch = prog[b % len(prog)]
        r0=b*BAR
        notes = CH[ch]
        for j,nm in enumerate(notes):
            out.append((r0, chn, note_for_name('pad', nm), I['Pad']))
    return out

def arpeggio(pat, prog, bars=4, chn=6, pattern=(0,1,2,1), octshift=12):
    out=[]
    for b in range(bars):
        ch = prog[b % len(prog)]
        r0=b*BAR
        notes = CH[ch]
        seq=[notes[pattern[i%len(pattern)]] for i in range(8)]
        for i,nm in enumerate(seq):
            r = i*2
            out.append((r0+r, chn, note_for_name('arp', nn_shift(nm, octshift)), I['Arp']))
    return out
